  "ui.finalOnboarding.fbcd710247": "Your connection is configured. Start with a question or describe what you want to build.",
  "ui.finalOnboarding.24fba6f166": "Connect an AI subscription",
  "ui.finalOnboarding.82d6b8daef": "Use supported agents such as Codex or OpenCode through Pixflow Design Bridge.",
  "ui.finalOnboarding.894f66ba11": "Use an API key",
  "ui.finalOnboarding.e76c3bfd0e": "Connect directly to your provider. API usage is billed separately.",
  "ui.finalOnboarding.1be451ef72": "Continue without AI",
  "ui.finalOnboarding.88e6e83b86": "Use the WordPress workspace. Add AI later if you want.",
  "ui.finalOnboarding.105e56e56f": "Why choose Local CLI?",
  "ui.finalOnboarding.5df057fcd7": "API usage is billed separately",
  "ui.finalOnboarding.44e30ed15f": "BYOK requires an API key. Your AI provider charges API usage separately from its CLI subscription, so this can cost extra instead of consuming the CLI account's included or weekly usage limits.",
  "ui.finalOnboarding.5f9b0ae108": "Session only",
  "ui.finalOnboarding.3c0e1f05da": "Keep context only while this panel session is open. Reload starts fresh.",
